class Vector2D {
private:
    vector<vector<int>> vec;
    int row;
    int col;

    void advance() {
        while (row < (int)vec.size() && col >= (int)vec[row].size()) {
            row++;
            col = 0;
        }
    }
public:
    Vector2D(vector<vector<int>>& vec) : vec(vec), row(0), col(0) {}

    int next() {
        advance();
        int val = vec[row][col++];
        return val;
    }

    bool hasNext() {
        advance();
        return row < (int)vec.size();
    }
};

class Vector2D {
    private int[][] vec;
    private int row;
    private int col;

    private void advance() {
        while (row < vec.length && col >= vec[row].length) {
            row++;
            col = 0;
        }
    }

    public Vector2D(int[][] vec) {
        this.vec = vec;
        this.row = 0;
        this.col = 0;
    }

    public int next() {
        advance();
        return vec[row][col++];
    }

    public boolean hasNext() {
        advance();
        return row < vec.length;
    }
}

/**
 * @param {number[][]} vec
 */
var Vector2D = function(vec) {
    this.vec = vec;
    this.row = 0;
    this.col = 0;
};

Vector2D.prototype.advance = function() {
    while (this.row < this.vec.length && this.col >= this.vec[this.row].length) {
        this.row++;
        this.col = 0;
    }
};

/**
 * @return {number}
 */
Vector2D.prototype.next = function() {
    this.advance();
    const val = this.vec[this.row][this.col];
    this.col++;
    return val;
};

/**
 * @return {boolean}
 */
Vector2D.prototype.hasNext = function() {
    this.advance();
    return this.row < this.vec.length;
};
